CREATE TABLE IF NOT EXISTS profiles(id text PRIMARY KEY, name text NOT NULL, email text UNIQUE NOT NULL, password_hash text NOT NULL, platform_admin boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES profiles, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_plans(id text PRIMARY KEY,name text NOT NULL,max_doctors int NOT NULL,max_users int NOT NULL,price_minor int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS clinics(id text PRIMARY KEY,name text NOT NULL,currency text NOT NULL DEFAULT 'EGP',timezone text NOT NULL DEFAULT 'Africa/Cairo',specialty text DEFAULT 'طب الأسرة',phone text DEFAULT '',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS clinic_memberships(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,user_id text NOT NULL REFERENCES profiles,role text NOT NULL CHECK(role IN('manager','receptionist','doctor','nurse','accountant')),medical_access boolean NOT NULL DEFAULT false,UNIQUE(clinic_id,user_id));
CREATE TABLE IF NOT EXISTS clinic_subscriptions(id text PRIMARY KEY,clinic_id text UNIQUE NOT NULL REFERENCES clinics,plan_id text NOT NULL REFERENCES subscription_plans,status text NOT NULL DEFAULT 'trial',trial_ends_at timestamptz NOT NULL DEFAULT now()+interval '14 days');
CREATE TABLE IF NOT EXISTS doctors(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,user_id text NOT NULL REFERENCES profiles,name text NOT NULL,specialty text NOT NULL,color text DEFAULT 'teal',UNIQUE(clinic_id,id));
CREATE TABLE IF NOT EXISTS services(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,name text NOT NULL,duration int NOT NULL CHECK(duration BETWEEN 5 AND 240),price_minor int NOT NULL CHECK(price_minor>=0),UNIQUE(clinic_id,id));
CREATE TABLE IF NOT EXISTS doctor_schedules(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,doctor_id text NOT NULL,weekday int NOT NULL CHECK(weekday BETWEEN 0 AND 6),start_hour int NOT NULL DEFAULT 9,end_hour int NOT NULL DEFAULT 21,FOREIGN KEY(clinic_id,doctor_id) REFERENCES doctors(clinic_id,id));
CREATE TABLE IF NOT EXISTS schedule_exceptions(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,doctor_id text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason text,FOREIGN KEY(clinic_id,doctor_id) REFERENCES doctors(clinic_id,id));
CREATE TABLE IF NOT EXISTS patients(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,file_number int NOT NULL,name text NOT NULL,phone text NOT NULL,birth_date date,estimated_age int CHECK(estimated_age BETWEEN 0 AND 130),gender text DEFAULT 'unspecified',address text DEFAULT '',emergency_contact text DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinic_id,id),UNIQUE(clinic_id,file_number));
CREATE INDEX IF NOT EXISTS patient_search ON patients(clinic_id,name,phone);
CREATE TABLE IF NOT EXISTS appointments(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,patient_id text NOT NULL,doctor_id text NOT NULL,service_id text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'booked' CHECK(status IN('booked','confirmed','arrived','in_progress','completed','cancelled','no_show')),reason text DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinic_id,id),FOREIGN KEY(clinic_id,patient_id) REFERENCES patients(clinic_id,id),FOREIGN KEY(clinic_id,doctor_id) REFERENCES doctors(clinic_id,id),FOREIGN KEY(clinic_id,service_id) REFERENCES services(clinic_id,id),CHECK(ends_at>starts_at));
CREATE INDEX IF NOT EXISTS appointment_day ON appointments(clinic_id,starts_at,doctor_id);
CREATE TABLE IF NOT EXISTS queue_entries(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,appointment_id text NOT NULL UNIQUE,arrived_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,priority int NOT NULL DEFAULT 0,reason text DEFAULT '',FOREIGN KEY(clinic_id,appointment_id) REFERENCES appointments(clinic_id,id));
CREATE TABLE IF NOT EXISTS encounters(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,appointment_id text NOT NULL UNIQUE,patient_id text NOT NULL,doctor_id text NOT NULL,status text NOT NULL DEFAULT 'draft',version int NOT NULL DEFAULT 1,content jsonb NOT NULL DEFAULT '{}',signed_at timestamptz,signed_by text REFERENCES profiles,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinic_id,id),FOREIGN KEY(clinic_id,appointment_id) REFERENCES appointments(clinic_id,id),FOREIGN KEY(clinic_id,patient_id) REFERENCES patients(clinic_id,id),FOREIGN KEY(clinic_id,doctor_id) REFERENCES doctors(clinic_id,id));
CREATE TABLE IF NOT EXISTS clinical_notes(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,encounter_id text NOT NULL,author_id text NOT NULL REFERENCES profiles,body text NOT NULL,created_at timestamptz DEFAULT now(),FOREIGN KEY(clinic_id,encounter_id) REFERENCES encounters(clinic_id,id));
CREATE TABLE IF NOT EXISTS vitals(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,encounter_id text NOT NULL,values jsonb NOT NULL,FOREIGN KEY(clinic_id,encounter_id) REFERENCES encounters(clinic_id,id));
CREATE TABLE IF NOT EXISTS prescriptions(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,encounter_id text NOT NULL UNIQUE,created_at timestamptz DEFAULT now(),UNIQUE(clinic_id,id),FOREIGN KEY(clinic_id,encounter_id) REFERENCES encounters(clinic_id,id));
CREATE TABLE IF NOT EXISTS prescription_items(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,prescription_id text NOT NULL,name text NOT NULL,strength text,dose text,frequency text,route text,duration text,notes text,FOREIGN KEY(clinic_id,prescription_id) REFERENCES prescriptions(clinic_id,id));
CREATE TABLE IF NOT EXISTS medical_attachments(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,patient_id text NOT NULL,title text NOT NULL,mime text NOT NULL,size int NOT NULL CHECK(size<=5242880),storage_key text NOT NULL,created_at timestamptz DEFAULT now(),FOREIGN KEY(clinic_id,patient_id) REFERENCES patients(clinic_id,id));
CREATE TABLE IF NOT EXISTS invoices(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,patient_id text NOT NULL,appointment_id text NOT NULL UNIQUE,number int NOT NULL,total_minor int NOT NULL CHECK(total_minor>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinic_id,id),UNIQUE(clinic_id,number),FOREIGN KEY(clinic_id,patient_id) REFERENCES patients(clinic_id,id),FOREIGN KEY(clinic_id,appointment_id) REFERENCES appointments(clinic_id,id));
CREATE TABLE IF NOT EXISTS invoice_items(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,invoice_id text NOT NULL,description text NOT NULL,amount_minor int NOT NULL CHECK(amount_minor>=0),FOREIGN KEY(clinic_id,invoice_id) REFERENCES invoices(clinic_id,id));
CREATE TABLE IF NOT EXISTS payments(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,invoice_id text NOT NULL,amount_minor int NOT NULL CHECK(amount_minor>0),method text NOT NULL CHECK(method IN('cash','card','wallet','transfer')),idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(clinic_id,id),UNIQUE(clinic_id,idempotency_key),FOREIGN KEY(clinic_id,invoice_id) REFERENCES invoices(clinic_id,id));
CREATE TABLE IF NOT EXISTS refunds(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,payment_id text NOT NULL,amount_minor int NOT NULL CHECK(amount_minor>0),reason text NOT NULL,idempotency_key text NOT NULL,created_at timestamptz DEFAULT now(),UNIQUE(clinic_id,idempotency_key),FOREIGN KEY(clinic_id,payment_id) REFERENCES payments(clinic_id,id));
CREATE TABLE IF NOT EXISTS expenses(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,category text NOT NULL,amount_minor int NOT NULL CHECK(amount_minor>0),method text NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_sessions(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,user_id text NOT NULL REFERENCES profiles,opening_minor int NOT NULL,actual_minor int,closed_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS invitations(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,email text NOT NULL,role text NOT NULL,token_hash text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS subscription_invoices(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,amount_minor int NOT NULL,status text NOT NULL DEFAULT 'manual_pending',created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS billing_events(id text PRIMARY KEY,clinic_id text REFERENCES clinics,provider_event_id text UNIQUE NOT NULL,payload jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_jobs(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,appointment_id text NOT NULL,channel text NOT NULL,status text NOT NULL DEFAULT 'not_connected',scheduled_at timestamptz,attempts int DEFAULT 0,FOREIGN KEY(clinic_id,appointment_id) REFERENCES appointments(clinic_id,id));
CREATE TABLE IF NOT EXISTS communication_preferences(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,patient_id text NOT NULL,consented boolean DEFAULT false,channel text DEFAULT 'none',FOREIGN KEY(clinic_id,patient_id) REFERENCES patients(clinic_id,id));
CREATE TABLE IF NOT EXISTS audit_logs(id text PRIMARY KEY,clinic_id text NOT NULL REFERENCES clinics,actor_id text NOT NULL,action text NOT NULL,entity_id text NOT NULL,created_at timestamptz DEFAULT now());
CREATE OR REPLACE FUNCTION current_clinic() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.clinic',true),'') $$;
CREATE OR REPLACE FUNCTION current_actor() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.actor',true),'') $$;
CREATE OR REPLACE FUNCTION app_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM clinic_memberships WHERE clinic_id=current_clinic() AND user_id=current_actor() $$;
CREATE OR REPLACE FUNCTION medical_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(bool_or(role='doctor' OR medical_access),false) FROM clinic_memberships WHERE clinic_id=current_clinic() AND user_id=current_actor() $$;
DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_roles WHERE rolname='clinic_app') THEN CREATE ROLE clinic_app NOLOGIN; END IF; END $$;
GRANT USAGE ON SCHEMA public TO clinic_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO clinic_app;
REVOKE ALL ON profiles,sessions FROM clinic_app;
GRANT SELECT ON subscription_plans TO clinic_app;
ALTER TABLE clinics ENABLE ROW LEVEL SECURITY;
CREATE POLICY clinic_scope ON clinics USING(id=current_clinic() AND app_role() IS NOT NULL) WITH CHECK(id=current_clinic() AND app_role()='manager');
ALTER TABLE clinic_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_scope ON clinic_memberships USING(clinic_id=current_clinic() AND app_role() IS NOT NULL) WITH CHECK(clinic_id=current_clinic() AND app_role()='manager');
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['doctors','services','doctor_schedules','schedule_exceptions','patients','appointments','queue_entries','invoices','invoice_items','payments','refunds','expenses','cash_sessions','invitations','clinic_subscriptions','subscription_invoices','billing_events','notification_jobs','communication_preferences','audit_logs'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_scope ON %I USING(clinic_id=current_clinic() AND app_role() IS NOT NULL) WITH CHECK(clinic_id=current_clinic() AND app_role() IS NOT NULL)',t);
END LOOP;
FOREACH t IN ARRAY ARRAY['encounters','clinical_notes','vitals','prescriptions','prescription_items','medical_attachments'] LOOP
EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY medical_scope ON %I USING(clinic_id=current_clinic() AND medical_access()) WITH CHECK(clinic_id=current_clinic() AND medical_access())',t);
END LOOP; END $$;
CREATE OR REPLACE FUNCTION prevent_overlap() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
PERFORM pg_advisory_xact_lock(hashtext(NEW.clinic_id||NEW.doctor_id));
IF NEW.status NOT IN('cancelled','no_show') AND EXISTS(SELECT 1 FROM appointments WHERE clinic_id=NEW.clinic_id AND doctor_id=NEW.doctor_id AND id<>NEW.id AND status NOT IN('cancelled','no_show') AND starts_at<NEW.ends_at AND ends_at>NEW.starts_at) THEN RAISE EXCEPTION 'APPOINTMENT_CONFLICT'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER appointment_overlap BEFORE INSERT OR UPDATE ON appointments FOR EACH ROW EXECUTE FUNCTION prevent_overlap();
CREATE OR REPLACE FUNCTION lock_signed() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='signed' THEN RAISE EXCEPTION 'SIGNED_ENCOUNTER_LOCKED'; END IF; RETURN NEW; END $$;
CREATE TRIGGER signed_lock BEFORE UPDATE OR DELETE ON encounters FOR EACH ROW EXECUTE FUNCTION lock_signed();
CREATE OR REPLACE FUNCTION create_staff_profile(uid text,uname text,uemail text,upassword text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF app_role()<>'manager' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; INSERT INTO profiles(id,name,email,password_hash) VALUES(uid,uname,uemail,upassword); END $$;
REVOKE ALL ON FUNCTION create_staff_profile(text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION create_staff_profile(text,text,text,text) TO clinic_app;
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['invoices','invoice_items','payments','refunds','expenses','cash_sessions'] LOOP
EXECUTE format('DROP POLICY tenant_scope ON %I',t);
EXECUTE format('CREATE POLICY finance_scope ON %I USING(clinic_id=current_clinic() AND app_role() IN (''manager'',''receptionist'',''accountant'')) WITH CHECK(clinic_id=current_clinic() AND app_role() IN (''manager'',''receptionist'',''accountant''))',t);
END LOOP;
FOREACH t IN ARRAY ARRAY['doctors','services','doctor_schedules','schedule_exceptions'] LOOP
EXECUTE format('DROP POLICY tenant_scope ON %I',t);
EXECUTE format('CREATE POLICY directory_read ON %I FOR SELECT USING(clinic_id=current_clinic() AND app_role() IS NOT NULL)',t);
EXECUTE format('CREATE POLICY directory_write ON %I FOR ALL USING(clinic_id=current_clinic() AND app_role()=''manager'') WITH CHECK(clinic_id=current_clinic() AND app_role()=''manager'')',t);
END LOOP;
END $$;
REVOKE DELETE ON ALL TABLES IN SCHEMA public FROM clinic_app;
REVOKE UPDATE ON payments,refunds,audit_logs,clinical_notes,prescription_items,prescriptions,invoice_items,invoices FROM clinic_app;
REVOKE INSERT,UPDATE ON clinic_subscriptions,subscription_invoices,subscription_plans,billing_events FROM clinic_app;
REVOKE INSERT,UPDATE ON invitations FROM clinic_app;
DROP POLICY medical_scope ON encounters;
CREATE POLICY encounter_scope ON encounters USING(clinic_id=current_clinic() AND medical_access() AND (app_role()<>'doctor' OR doctor_id IN(SELECT id FROM doctors WHERE user_id=current_actor()))) WITH CHECK(clinic_id=current_clinic() AND medical_access() AND (app_role()<>'doctor' OR doctor_id IN(SELECT id FROM doctors WHERE user_id=current_actor())));
